/* === 顶栏高度 & 头像大小 === */
:root {
  --chat-header-height: 130px;
  --chat-header-avatar-size: 48px;
  --back-btn-icon: url('https://nos.netease.com/ysf/2e5582683fc5f10865e2ab592bfdd40b.png');
