/* === 返回箭头 === */
.header-btn-back {
  position: relative !important;
  left: 60px !important;
  top: -35px !important;
}

.header-btn-back svg {
  display: none !important;
}

.header-btn-back::before {
  content: '';
  display: block;
  width: 65px;
  height: 65px;
  background-image: var(--back-btn-icon);
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  position: absolute;
  left: 20%;
  top: 50%;
  transform: translate(-50%, -50%);
}

