/* ========== 气泡 ========== */

/* === 气泡内边距 === */
:root {
  --bubble-me-padding: 4px 14px;
  --bubble-them-padding: 4px 14px;
}

/* === 我方气泡 === */
.bubble-me-custom {
  background: #FEF7F9 !important;
  background-image: none !important;
  border: 1px solid #C9BCC0 !important;
  color: #333 !important;
  border-radius: 18px 4px 18px 18px !important;
  position: relative !important;
  overflow: visible !important;
}

/* 左上角贴图 */
.bubble-me-custom::before {
  content: '';
  display: block;
  position: absolute;
  top: -20px;
  left: -8px;
  width: 34px;
  height: 34px;
  background-image: url('https://nos.netease.com/ysf/773d1b6a2506c2eb2c5f675dda47d34a.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
  z-index: 5;
}

/* === 对方气泡 === */
.bubble-them-custom {
  background: #fff !important;
  background-image: none !important;
  border: 1px solid #e5e5e5 !important;
  color: #333 !important;
  border-radius: 4px 18px 18px 18px !important;
  position: relative !important;
  overflow: visible !important;
}

/* 右下角贴图 */
.bubble-them-custom::after {
  content: '';
  display: block;
  position: absolute;
  bottom: -20px;
  right: 1px;
  width: 24px;
  height: 24px;
