/* ========== 引用消息 ========== */

/* === 隐藏气泡内引用块 === */
.msg-reply-block {
  display: none !important;
}

/* === 启用气泡外独立引用块 === */
.msg-reply-block-detached {
  display: flex !important;
  background: #fff !important;
  border: 1px solid #e5e5e5 !important;
  border-radius: 8px !important;
  padding: 6px 12px !important;
  margin-bottom: 6px !important;
  max-width: 110% !important;
  min-height: auto !important;
}

/* 引用文字 — 单行，超出省略号 */
.msg-reply-detached-text {
  display: block !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  max-width: 100% !important;
}

/* 引用标题名字颜色 */
.msg-reply-detached-name {
  color: #444 !important;
}

/* ✅ 只改聊天表情包 · 绝对不碰头像 ✅ */
/* 核心：只选中【不包含头像】的气泡，彻底排除头像区域 */

/* 只清除表情包的气泡边框、背景、内边距、阴影 */
div[class*="message"] div[class*="bubble"]:has(img):not(:has([class*="avatar"])) {
  background: transparent !important; /* 清除气泡背景色 */
  border: none !important; /* 彻底去掉边框线 */
  box-shadow: none !important; /* 清除气泡的立体阴影 */
  padding: 0 !important; /* 消除图片和气泡之间的空隙 */
  border-radius: 0 !important; /* 去掉气泡圆角，如需保留可删除此行 */
  outline: none !important; /* 清除可能的外轮廓线 */
}

/* 只控制表情包的尺寸，完全不影响头像 */
div[class*="message"] div[class*="bubble"]:not(:has([class*="avatar"])) img {
  width: 100px !important;
  height: 100px !important;
  max-width: 100px !important;
  max-height: 100px !important;
  transform: scale(1.0) !important;
  /* 可选补充：去掉图片自带的圆角/边框，不需要可删除 */
  border-radius: 0 !important;
  border: none !important;
}
